import { Block, Text } from "@prototyp/skeletor";
import { FlashList } from "@shopify/flash-list";
import type {
  EventTimelineItem,
  ImageMessageContent,
  VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { type FC, useCallback } from "react";
import { StyleSheet } from "react-native";
import { Loading } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MediaThumbnail } from "../media-thumbnail";

const NUM_COLUMNS = 4;
const SPACING = 2;

const keyExtractor = (item: EventTimelineItem) => {
  const eventId = item.eventOrTransactionId;
  if (eventId?.tag === "EventId") return eventId.inner.eventId;
  if (eventId?.tag === "TransactionId") return eventId.inner.transactionId;
  return String(item.timestamp);
};

interface Props {
  items: EventTimelineItem[];
  loading: boolean;
  isEmpty: boolean;
  onPressItem: (
    uri: string | null,
    type?: "image" | "video",
    content?: ImageMessageContent | VideoMessageContent,
  ) => void;
}

export const MediaList: FC<Props> = ({
  items,
  loading,
  isEmpty,
  onPressItem,
}) => {
  const ListEmpty = useCallback(() => {
    if (loading) {
      return (
        <Block align="center" justify="center" flex={1} paddings={40}>
          <Loading isFullScreen={false} />
        </Block>
      );
    }

    return (
      <Block align="center" justify="center" flex={1} paddings={40}>
        <Text size={TextSize.medium} color={Colors.white50}>
          No media found
        </Text>
      </Block>
    );
  }, [loading]);

  return (
    <FlashList
      data={items}
      renderItem={({ item, index }) => (
        <Block
          margins={{
            marginRight: (index + 1) % NUM_COLUMNS === 0 ? 0 : SPACING,
            marginBottom: SPACING,
          }}
        >
          <MediaThumbnail item={item} onPress={onPressItem} />
        </Block>
      )}
      keyExtractor={keyExtractor}
      numColumns={NUM_COLUMNS}
      contentContainerStyle={styles.listContent}
      ListEmptyComponent={ListEmpty}
      ListFooterComponent={
        loading && !isEmpty ? (
          <Block align="center" justify="center" flex={1} paddings={40}>
            <Loading isFullScreen={false} />
          </Block>
        ) : null
      }
      showsVerticalScrollIndicator={false}
    />
  );
};

const styles = StyleSheet.create({
  listContent: {
    padding: SPACING,
    flexGrow: 1,
  },
});

import { Block } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
  type VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { type FC, useEffect, useState } from "react";
import { Dimensions, Image, StyleSheet } from "react-native";
import { Button, Loading } from "shared/components";
import { Colors } from "shared/styles";
import { resolveEncryptedImage } from "shared/utils/encrypted-image-cache";

const NUM_COLUMNS = 4;
const SPACING = 2;
const HORIZONTAL_SPACING = 40; // Each padding is 20px
const { width: SCREEN_WIDTH } = Dimensions.get("window");
const ITEM_SIZE =
  (SCREEN_WIDTH - SPACING * (NUM_COLUMNS + 1) - HORIZONTAL_SPACING) /
  NUM_COLUMNS;

interface MediaThumbnailProps {
  item: EventTimelineItem;
  onPress: (
    uri: string | null,
    type?: "image" | "video",
    content?: ImageMessageContent | VideoMessageContent,
  ) => void;
}

function getMediaInfo(item: EventTimelineItem): {
  type: "image" | "video";
  content: ImageMessageContent | VideoMessageContent;
} | null {
  if (item.content.tag === TimelineItemContent_Tags.MsgLike) {
    const content = item.content.inner.content;
    if (content.kind.tag === MsgLikeKind_Tags.Message) {
      const msgType = content.kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return { type: "image", content: msgType.inner.content };
      }
      if (msgType?.tag === MessageType_Tags.Video) {
        return { type: "video", content: msgType.inner.content };
      }
    }
  }
  return null;
}

export const MediaThumbnail: FC<MediaThumbnailProps> = ({ item, onPress }) => {
  const [uri, setUri] = useState<string | null>(null);
  const [info, setInfo] = useState<{
    type: "image" | "video";
    content: ImageMessageContent | VideoMessageContent;
  } | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadMedia = async () => {
      try {
        setLoading(true);
        const info = getMediaInfo(item);
        setInfo(info);
        if (!info) return;

        if (info.type === "image") {
          const mxcUrl = info.content.source.url();
          if (!mxcUrl) return;

          const resolved = await resolveEncryptedImage({
            cacheKey: mxcUrl,
            mediaSource: info.content.source,
            mimeType: info.content.info?.mimetype || "image/jpeg",
          });
          if (resolved) setUri(resolved);
        } else {
          const videoContent = info.content as VideoMessageContent;
          const thumbSource = videoContent.info?.thumbnailSource;
          if (!thumbSource) return;
          const mxcUrl = thumbSource.url();
          if (!mxcUrl) return;

          const resolved = await resolveEncryptedImage({
            cacheKey: mxcUrl,
            mediaSource: thumbSource,
            mimeType: "image/jpeg",
          });
          if (resolved) setUri(resolved);
        }
      } catch (e) {
        console.error("Failed to load media thumbnail:", e);
      } finally {
        setLoading(false);
      }
    };

    loadMedia();
  }, [item]);

  return (
    <Button.Wrapper onPress={() => onPress(uri, info?.type, info?.content)}>
      <Block
        width={ITEM_SIZE}
        height={ITEM_SIZE}
        background={Colors.white20}
        border={{ borderRadius: 4 }}
        overflow="hidden"
        align="center"
        justify="center"
      >
        {uri ? (
          <Image
            source={{ uri }}
            width={ITEM_SIZE}
            height={ITEM_SIZE}
            resizeMode="cover"
          />
        ) : (
          loading && <Loading isFullScreen={false} />
        )}

        {info?.type === "video" && !loading && (
          <Block
            absolute
            offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
            align="center"
            justify="center"
            pointerEvents="none"
          >
            <Block
              background={Colors.primary}
              width={24}
              height={24}
              align="center"
              justify="center"
              border={{ borderRadius: 999 }}
            >
              <Image
                tintColor={Colors.white}
                source={require("assets/icons/play.png")}
                style={styles.playButton}
              />
            </Block>
          </Block>
        )}
      </Block>
    </Button.Wrapper>
  );
};

const styles = StyleSheet.create({
  playButton: {
    width: 16,
    height: 16,
  },
});

